SELECT r.revision, r.namespace, r.client_id, r.session_id, r.attempt_id, r.selection_id, r.selected_revision, r.grant_id, r.origin, r.profile_channel, r.browser_instance, r.document_id, r.document_generation, r.tab_id, r.broker_epoch, r.channel_epoch, r.scope_hash, r.renderer_lease_id, r.renderer_lease_generation, r.chrome_start_token, r.native_host_start_token, r.dispatch_state, r.protection_state, r.created_at, r.updated_at, r.purpose_hash FROM (SELECT * FROM  (SELECT d.* FROM credential_delivery_attempts d WHERE d.namespace=:Namespace AND d.client_id=:ClientID AND d.attempt_id=:AttemptID
)  deliveries) r WHERE $criteria.CompositeIn("r", $CredentialDeliveryFinishKeys)